-- P2 concurrency hardening: submission and computation serialize on the exact
-- same benchmark-cell advisory lock before the sealed-state decision.
create or replace function public.submit_benchmark_contribution(p_organization_id uuid,p_metric_code text,p_segment_key text,p_period_start date,p_period_end date,p_value_exact numeric,p_input_version text,p_source_hash text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();h text;r jsonb;cached jsonb;cid uuid;
begin
 if a is null or not private.has_org_role(p_organization_id,array['CLIENT_OWNER','CLIENT_ADMIN'],a)then raise exception'BENCHMARK_CONTRIBUTION_DENIED'using errcode='42501';end if;
 if p_metric_code!~'^[A-Z][A-Z0-9_.-]{1,119}$'or p_segment_key!~'^[A-Z][A-Z0-9_.-]{1,119}$'or p_period_start is null or p_period_end<p_period_start or length(btrim(coalesce(p_input_version,'')))not between 1 and 120 or p_source_hash!~'^[0-9a-f]{64}$'then raise exception'INVALID_BENCHMARK_CONTRIBUTION'using errcode='22023';end if;
 h:=private.canonical_request_hash(jsonb_build_object('organization',p_organization_id,'metric',p_metric_code,'segment',p_segment_key,'period_start',p_period_start,'period_end',p_period_end,'value',p_value_exact,'input_version',p_input_version,'source_hash',p_source_hash));cached:=private.begin_contract_command(p_organization_id,'benchmark.contribution.submit',p_idempotency_key,h,a);if cached is not null then return cached;end if;
 perform pg_advisory_xact_lock(hashtextextended('benchmark-cell:'||p_metric_code||':'||p_segment_key||':'||p_period_start::text||':'||p_period_end::text,0));
 if exists(select 1 from public.benchmark_publications publication_row where publication_row.metric_code=p_metric_code and publication_row.segment_key=p_segment_key and publication_row.period_start=p_period_start and publication_row.period_end=p_period_end)then raise exception'BENCHMARK_CELL_SEALED'using errcode='55000';end if;
 insert into private.benchmark_contributions(organization_id,metric_code,segment_key,period_start,period_end,value_exact,input_version,source_hash,submitted_by,correlation_id)values(p_organization_id,p_metric_code,p_segment_key,p_period_start,p_period_end,p_value_exact,p_input_version,p_source_hash,a,p_correlation_id)returning id into cid;
 r:=jsonb_build_object('outcome','BENCHMARK_CONTRIBUTION_ACCEPTED','contribution_id',cid,'metric_code',p_metric_code,'period_end',p_period_end);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_organization_id,a,'USER','benchmark.contribution.submitted','benchmark_contribution',cid::text,p_correlation_id,jsonb_build_object('metric_code',p_metric_code,'segment_key',p_segment_key,'period_start',p_period_start,'period_end',p_period_end,'input_version',p_input_version,'source_hash',p_source_hash),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_organization_id,'benchmark_contribution',cid::text,'BenchmarkContributionAcceptedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_organization_id,'benchmark.contribution.submit',p_idempotency_key,r);return r;
end$$;
revoke all on function public.submit_benchmark_contribution(uuid,text,text,date,date,numeric,text,text,text,uuid)from public,anon,authenticated,service_role;
grant execute on function public.submit_benchmark_contribution(uuid,text,text,date,date,numeric,text,text,text,uuid)to authenticated;
notify pgrst,'reload schema';
